// Connection string lists all replica set members
// The driver automatically handles failover when primary changes
const uri = 'mongodb://host1:27017,host2:27017,host3:27017/?replicaSet=myReplicaSet';

// MongoDB Atlas provides this automatically:
const atlasUri = 'mongodb+srv://user:pass@cluster0.mongodb.net/mydb?retryWrites=true&w=majority';
// 'mongodb+srv://' — SRV record resolves to all 3 replica set members
// retryWrites=true  — automatically retry writes on network blips
// w=majority        — wait for majority acknowledgement (data safety)

const client = new MongoClient(atlasUri);
await client.connect();
// The driver is now replica-set-aware — it knows all members
// and will automatically reconnect to the new primary if failover occurs

// w: 1 (default) — acknowledged by primary only
// Fast but: if primary crashes before replicating, write may be lost
await db.collection('logs').insertOne(
  { event: 'page_view', url: '/home' },
  { writeConcern: { w: 1 } }  // OK for non-critical data
);

// w: 'majority' — acknowledged by majority of voting members
// Slightly slower but: write survives primary failure
await db.collection('orders').insertOne(
  { userId: id, items: cart, total: 2499 },
  { writeConcern: { w: 'majority' } }  // critical data — use majority!
);

// w: 0 — fire and forget (not acknowledged)
// Fastest but no guarantees — only for truly throwaway data
await analytics.insertOne(
  { event: 'ad_impression' },
  { writeConcern: { w: 0 } }  // we don't care if a few are lost
);

// Set at collection level (applies to all operations)
const orders = db.collection('orders').withOptions({
  writeConcern: { w: 'majority', j: true }  // j: true = also wait for journal flush
});

// primaryPreferred — read from primary, fallback to secondary if unavailable
const db = client.db('myapp', {
  readPreference: 'primaryPreferred'
});

// secondary — always read from a secondary (never primary)
// Good for analytics/reporting that can tolerate slight staleness
const analyticsDb = client.db('myapp', {
  readPreference: 'secondary'
});

// nearest — read from the replica set member with lowest network latency
// Good for globally distributed apps with read replicas in different regions
const nearestDb = client.db('myapp', {
  readPreference: 'nearest'
});

// Per-operation read preference override:
const recentOrders = await db.collection('orders').find(
  { status: 'pending' },
  { readPreference: 'primary' }  // must read from primary for strong consistency
).toArray();

// Read preferences:
// primary — always from primary (default)
// primaryPreferred — primary if available, secondary if not
// secondary — always from secondary (may be slightly stale)
// secondaryPreferred — secondary if available, primary if not
// nearest — lowest latency member

// Watch for changes to the orders collection
const changeStream = db.collection('orders').watch();

// Process each change event
for await (const change of changeStream) {
  console.log('Change type:', change.operationType); // insert, update, delete
  console.log('Document ID:', change.documentKey._id);

  if (change.operationType === 'insert') {
    const newOrder = change.fullDocument;
    await sendConfirmationEmail(newOrder.userId, newOrder);
  }

  if (change.operationType === 'update') {
    const { updatedFields } = change.updateDescription;
    if (updatedFields.status === 'shipped') {
      await sendShippingNotification(change.documentKey._id);
    }
  }
}

// Resume after restart using resumeToken
const token = loadResumeToken();  // load from storage
const resumedStream = db.collection('orders').watch([], {
  resumeAfter: token  // picks up exactly where it left off
});
